-- Прогон 01_hq_free_rebuild.sql без следов, одной строкой для SQL-редактора Supabase. Всегда заканчивается ошибкой «DRYRUN (всё откатано)».
-- Клан со штабом и 1000+ в общаке, его глава: падение → бесплатное восстановление → второе падение → восстановление за 1000.
do $d$ declare v_clan bigint; v_leader uuid; v_hq text; v_t2 text; b0 int; b1 int; b2 int; r text := ''; v_used boolean; v_free boolean; v_cost int; begin set local lock_timeout = '3s'; execute $q$ alter table public.clan_treasury add column if not exists hq_free_rebuild_used boolean not null default false $q$; execute $q$ create or replace function public.clan_hq_place(p_territory_id text) returns void language plpgsql security definer set search_path = public as $f$ declare v_clan bigint; v_e public.clan_economy; v_cur public.clan_hq; v_cost int; v_free boolean := false; begin select clan_id into v_clan from public._my_clan_membership(auth.uid()); perform public._clan_leader_check(v_clan); select * into v_e from public.clan_economy where id = 1; if not public._clan_econ_on(v_clan) then raise exception 'CLAN:treasury_off'; end if; if exists (select 1 from public.clan_hq_ruins r where r.clan_id = v_clan and r.until > now()) then raise exception 'CLAN:hq_ruins'; end if; if not exists (select 1 from public.territories t join public.clan_members cm on cm.user_id = t.owner_id and cm.clan_id = v_clan and cm.left_at is null where t.id = p_territory_id and not t.is_deleted) then raise exception 'CLAN:hq_not_ours'; end if; if exists (select 1 from public.clan_hq h where h.territory_id = p_territory_id) then raise exception 'CLAN:hq_taken'; end if; select * into v_cur from public.clan_hq where clan_id = v_clan for update; if v_cur.clan_id is not null and coalesce(v_cur.moved_at, v_cur.placed_at) + interval '3 days' > now() then raise exception 'CLAN:hq_cooldown'; end if; v_cost := case when v_cur.clan_id is null then v_e.hq_place_cost else v_e.hq_move_cost end; if v_cur.clan_id is null and exists (select 1 from public.clan_hq_ruins r where r.clan_id = v_clan) and not coalesce((select t.hq_free_rebuild_used from public.clan_treasury t where t.clan_id = v_clan), false) then v_free := true; v_cost := 0; end if; if v_cost > 0 then perform public._clan_treasury_spend(v_clan, v_cost, 'spend_hq', auth.uid(), 'Штаб-квартира · ' || p_territory_id); end if; if v_free then insert into public.clan_treasury (clan_id) values (v_clan) on conflict do nothing; update public.clan_treasury set hq_free_rebuild_used = true where clan_id = v_clan; end if; delete from public.clan_sieges where clan_id = v_clan; delete from public.clan_hq_ruins where clan_id = v_clan; if v_cur.clan_id is null then insert into public.clan_hq (clan_id, territory_id) values (v_clan, p_territory_id); else update public.clan_hq set territory_id = p_territory_id, moved_at = now(), defense_at = now() where clan_id = v_clan; end if; end $f$ $q$; execute $q$ create or replace function public.clan_hq_free_rebuild(p_clan_id bigint) returns boolean language sql stable security definer set search_path = public as $f$ select not exists (select 1 from public.clan_hq h where h.clan_id = p_clan_id) and exists (select 1 from public.clan_hq_ruins r where r.clan_id = p_clan_id) and not coalesce((select t.hq_free_rebuild_used from public.clan_treasury t where t.clan_id = p_clan_id), false); $f$ $q$; execute $q$ revoke all on function public.clan_hq_free_rebuild(bigint) from public, anon $q$; execute $q$ grant execute on function public.clan_hq_free_rebuild(bigint) to authenticated $q$; select h.clan_id, h.territory_id, t.balance into v_clan, v_hq, b0 from public.clan_hq h join public.clan_treasury t on t.clan_id = h.clan_id where t.balance >= 1000 and public._clan_econ_on(h.clan_id) and not exists (select 1 from public.clan_sieges s where s.clan_id = h.clan_id) order by t.balance limit 1; if v_clan is null then raise exception 'DRYRUN: no clan with HQ and 1000+'; end if; select cm.user_id into v_leader from public.clan_members cm where cm.clan_id = v_clan and cm.left_at is null and cm.role = 'leader' limit 1; select t.id into v_t2 from public.territories t join public.clan_members cm on cm.user_id = t.owner_id and cm.clan_id = v_clan and cm.left_at is null where not t.is_deleted and t.id <> v_hq limit 1; r := r || 'клан ' || v_clan || ', баланс ' || b0 || ', штаб ' || v_hq || ', второй сектор ' || v_t2 || '; '; delete from public.clan_hq where clan_id = v_clan; insert into public.clan_hq_ruins (clan_id, territory_id, by_clan_id, by_user, loot, until) values (v_clan, v_hq, null, null, 0, now() - interval '1 minute') on conflict (clan_id) do update set until = excluded.until; perform set_config('request.jwt.claims', json_build_object('sub', v_leader, 'role', 'authenticated')::text, true); set local role authenticated; v_free := public.clan_hq_free_rebuild(v_clan); r := r || '1) после падения бесплатно доступно: ' || v_free || '; '; perform public.clan_hq_place(v_t2); reset role; select balance, hq_free_rebuild_used into b1, v_used from public.clan_treasury where clan_id = v_clan; r := r || '2) восстановили на ' || v_t2 || ': списано ' || (b0 - b1) || ', отметка ' || v_used || ', руин ' || (select count(*) from public.clan_hq_ruins where clan_id = v_clan) || ', штаб ' || coalesce((select territory_id from public.clan_hq where clan_id = v_clan), 'нет') || '; '; delete from public.clan_hq where clan_id = v_clan; insert into public.clan_hq_ruins (clan_id, territory_id, by_clan_id, by_user, loot, until) values (v_clan, v_t2, null, null, 0, now() - interval '1 minute'); set local role authenticated; v_free := public.clan_hq_free_rebuild(v_clan); r := r || '3) после второго падения бесплатно: ' || v_free || '; '; perform public.clan_hq_place(v_hq); reset role; select balance into b2 from public.clan_treasury where clan_id = v_clan; r := r || '4) второе восстановление: списано ' || (b1 - b2) || ', штаб ' || coalesce((select territory_id from public.clan_hq where clan_id = v_clan), 'нет') || '; '; r := r || '5) anon может вызвать: ' || has_function_privilege('anon', 'public.clan_hq_free_rebuild(bigint)', 'execute') || ', authenticated: ' || has_function_privilege('authenticated', 'public.clan_hq_free_rebuild(bigint)', 'execute'); raise exception 'DRYRUN (всё откатано): %', r; end $d$;
